        type: "p",
        text: "这篇文章写给正在推进 PC 项目的独立开发者。不是给新手。不是理论课。我们会拆解为什么愿望单增长在现实中会停滞，以及团队如何建立一个能支撑稳定进展的系统，而不是反复 reset。",
